// @id Q-K-10#2
// (b) failed re-anchor: a newer capture exists and no locator on it re-anchors this one (unchanged from the packet)
MATCH (src:Source)-[:HAS_SNAPSHOT]->(old:SourceSnapshot)-[:HAS_LOCATOR]->(loc:SourceLocator)<-[:HAS_EVIDENCE]-(a:Assertion)
MATCH (src)-[:HAS_SNAPSHOT]->(newer:SourceSnapshot) WHERE coalesce(newer.observedAt, newer.retrievedAt) > coalesce(old.observedAt, old.retrievedAt)
  AND NOT EXISTS { MATCH (newer)-[:HAS_LOCATOR]->(l2:SourceLocator) WHERE l2.reanchorsLocatorUid = loc.uid }
RETURN DISTINCT a.uid AS assertion, loc.uid AS locator, old.contentHash AS oldCapture, newer.contentHash AS newerCapture

// @id CQ-ID-04
// @param rt:datetime
// @param vt:datetime
MATCH (s:ChemicalSubstance {uid: $sUid})
MATCH (s)-[l:HAS_IDENTIFIER]->(i:Identifier)            // kernel: Subjectable -> Identifier (Identifier.identifies is IN), IdentifierLinkProperties episode
WHERE l.recordedFrom <= $rt AND (l.recordedTo IS NULL OR l.recordedTo > $rt)
  AND (l.validFrom IS NULL OR l.validFrom <= $vt) AND (l.validTo IS NULL OR l.validTo > $vt)
// R-42: i identifies s only. A disagreement is the same (scheme, normalized value) from another issuer, held by another record:
// two Identifier nodes compared by value, reported for review, never identity.
CALL (s, i) {
  OPTIONAL MATCH (other)-[ol:HAS_IDENTIFIER]->(oi:Identifier)
  WHERE oi.scheme = i.scheme AND oi.value = i.value AND oi.issuer <> i.issuer AND other <> s AND ol.recordedTo IS NULL
  RETURN collect(DISTINCT CASE WHEN oi IS NULL THEN null ELSE
           {holder: other.uid, holderKind: [lb IN labels(other) WHERE lb <> 'Entity'][0], issuer: oi.issuer, link: ol.assertionUid} END) AS sameValueElsewhere
}
// TRACE over the identifier link assertion: the authority record and snapshot that assign i to s
CALL (l) {
  OPTIONAL MATCH (ta:Assertion {uid: l.assertionUid})
  OPTIONAL MATCH (ta)-[tev:HAS_EVIDENCE]->(tloc:SourceLocator)<-[:HAS_LOCATOR]-(tsnap:SourceSnapshot)<-[:HAS_SNAPSHOT]-(tsrc:Source)
  OPTIONAL MATCH (ta)-[:ASSERTED_BY]->(twho)
  OPTIONAL MATCH (tadj:Adjudication)-[:ASSESSES]->(ta) WHERE tadj.recordedTo IS NULL
  RETURN collect(DISTINCT CASE WHEN ta IS NULL THEN null ELSE
           {assertion: ta.uid, status: ta.status, asserter: twho.uid, role: tev.role, selectorKind: tloc.selectorKind, exact: tloc.exact,
            snapshot: tsnap.uid, contentHash: tsnap.contentHash, retrievedAt: tsnap.retrievedAt, source: tsrc.canonicalUri,
            adjudicationKind: tadj.adjudicationKind, verdict: tadj.verdict} END) AS authority
}
WITH s, collect({scheme: i.scheme, issuer: i.issuer, value: i.value, normalizationRule: i.normalizationRule, isPrimary: l.isPrimary,
                 link: l.assertionUid, validFrom: l.validFrom, authority: authority, sameValueElsewhere: sameValueElsewhere}) AS identifiers
// RESOLUTION / EQUIVALENCE judgments about s (rejected or disputed matches; R-42 rules.bridges)
CALL (s) {
  OPTIONAL MATCH (asmt:Assessment)-[:ASSESSES]->(s)
  WHERE asmt.assessmentKind IN ['RESOLUTION', 'EQUIVALENCE'] AND asmt.recordedTo IS NULL
  RETURN collect(DISTINCT asmt {.uid, .assessmentKind, .assessmentSubkind, .verdict, .status}) AS judgments
}
RETURN s.uid AS substance, s.name AS name, identifiers, judgments

// @id Q-D8-19
// $productUids = the products of ingredient X being compared; $V = valid time; $R = recorded time
MATCH (p:Product) WHERE p.uid IN $productUids
OPTIONAL MATCH (p)-[:HAS_VARIANT]->(pv:ProductVariant)
WITH p, collect(DISTINCT pv) AS variants
// R-73: measured content of a sold product = MEASURED QualityResults on its lots (or its variants' lots)
CALL (p, variants) {
  UNWIND [p] + variants AS lotTarget
  MATCH (lot:Lot)-[:LOT_OF]->(lotTarget)
  MATCH (q:QualityResult {resultBasis: 'MEASURED'})-[qf:QUALITY_RESULT_FOR]->(lot)
  OPTIONAL MATCH (q)-[:ISSUED_BY]->(lab:Organization)
  RETURN collect(DISTINCT {result: q.uid, lot: lot.lotCode, analyte: q.analyteVerbatim, value: q.value, unit: q.unitCode,
                           labelClaim: q.labelClaimValue, pctOfClaim: q.percentOfLabelClaimStated, lab: lab.name,
                           testedAt: q.testedAt, assertionUid: qf.assertionUid}) AS lotMeasurements
}
// R-73: lot-less survey rows stay the D1 predicate MEASURED_CONTENT_IN_PRODUCT (subject Product | ProductVariant)
CALL (p, variants) {
  UNWIND [p] + variants AS sampled
  MATCH (sa:Assertion {predicate: 'MEASURED_CONTENT_IN_PRODUCT'})-[:HAS_SUBJECT]->(sampled)
  WHERE sa.recordedTo IS NULL
  MATCH (sa)-[:HAS_OBJECT]->(cs:ChemicalSubstance)
  RETURN collect(DISTINCT {substance: cs.name, value: sa.valueNumber, unit: sa.unitCode, qualifiers: sa.qualifiers,
                           assertionUid: sa.uid}) AS surveyMeasurements
}
// certification coverage as of V on the product, its variants or their lots (CertificationCoverageTarget)
CALL (p, variants) {
  UNWIND [p] + variants AS covered
  OPTIONAL MATCH (covLot:Lot)-[:LOT_OF]->(covered)
  WITH covered, [covered] + collect(covLot) AS coverTargets
  UNWIND coverTargets AS ct
  MATCH (cl:CertificationListing)-[cv:COVERS]->(ct)
  WHERE (cv.validFrom IS NULL OR cv.validFrom <= $V) AND (cv.validTo IS NULL OR $V < cv.validTo)
    AND cv.recordedFrom <= $R AND (cv.recordedTo IS NULL OR $R < cv.recordedTo)
  RETURN collect(DISTINCT {listing: cl.uid, programme: cl.programme, standard: cl.standard, scope: cl.scopeVerbatim,
                           validFrom: cv.validFrom, validTo: cv.validTo, assertionUid: cv.assertionUid}) AS certifications
}
OPTIONAL MATCH (rec:RegulatoryRecord {recordFamily: 'ENFORCEMENT'})-[:CONCERNS]->(p)
RETURN p.uid, p.name, lotMeasurements, surveyMeasurements, certifications, count(DISTINCT rec) AS enforcementCount
// published: (rep:Report {reportKind: 'COMPARISON'})-[:DERIVED_FROM]->(the row Assertions), under a D10 DecisionCriterion version

// @id Q-D9-19#drop
CALL gds.graph.drop('d9-retelling-' + $frontierUid, false) YIELD graphName
RETURN graphName

// @gds G-5
MATCH (orig:Assertion)<-[:DERIVED_FROM]-(ret:Assertion)-[:OCCURS_IN]->(w:MediaWork)
WHERE (ret)-[:OCCURRENCE_OF]->(:Claim) AND w.publishedAt >= $asOf - duration({months: 24})
  AND EXISTS { MATCH (ret)-[:HAS_SUBJECT|HAS_OBJECT]->(x)
               WHERE EXISTS { (x)-[:ON_FRONTIER]->(:Frontier {key: $frontierKey}) }
                  OR EXISTS { (x)<-[:INVOLVES]-(:Event)-[:ON_FRONTIER]->(:Frontier {key: $frontierKey}) } }
MATCH (orig)-[:ASSERTED_BY]->(source), (ret)-[:ASSERTED_BY]->(target)
WHERE source <> target AND (source:Person OR source:Channel) AND (target:Person OR target:Channel)
WITH source, target, count(*) AS weight
RETURN gds.graph.project('d9-retelling-' + $frontierKey, target, source, {relationshipProperties: {weight: weight}})
